/**
 * @name Command injection via subprocess with user input
 * @description Using subprocess with shell=True or untrusted input can lead to command injection
 * @kind path-problem
 * @problem.severity error
 * @id py/command-injection
 * @tags security
 *        external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module CommandInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      // Match subprocess.call, subprocess.run, subprocess.Popen, os.system, etc.
      exists(API::CallNode apiCall |
        apiCall = call.getACall() and
        (
          // subprocess module calls
          apiCall = API::moduleImport("subprocess").getMember(["call", "run", "Popen", "check_call", "check_output"]).getACall() or
          // os.system and os.popen
          apiCall = API::moduleImport("os").getMember(["system", "popen"]).getACall() or
          // os.popen2, os.popen3, os.popen4
          apiCall = API::moduleImport("os").getMember(["popen2", "popen3", "popen4"]).getACall() or
          // Built-in exec, eval
          apiCall = API::builtin("exec").getACall() or
          apiCall = API::builtin("eval").getACall()
        )
      ) and
      sink = call.getArg(0)  // First argument is the command
    )
  }
}

module CommandInjectionFlow = TaintTracking::Global<CommandInjectionConfig>;
import CommandInjectionFlow::PathGraph

from CommandInjectionFlow::PathNode source, CommandInjectionFlow::PathNode sink
where CommandInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Command injection from $@.", source.getNode(), "user input"

/**
 * @name Path traversal vulnerability
 * @description Improper path validation leading to directory traversal attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      exists(API::CallNode apiCall |
        apiCall = call.getACall() and
        (
          // File open operations
          apiCall = API::builtin("open").getACall() or
          // os.path.join with user input
          apiCall = API::moduleImport("os").getMember("path").getMember("join").getACall() or
          // shutil file operations
          apiCall = API::moduleImport("shutil").getMember(["copy", "copy2", "copyfile", "copytree", "move", "rmtree"]).getACall() or
          // os file operations
          apiCall = API::moduleImport("os").getMember(["remove", "unlink", "rmdir", "mkdir", "makedirs", "rename", "replace"]).getACall() or
          apiCall = API::moduleImport("os").getMember(["chdir", "chmod", "chown", "stat", "lstat"]).getACall() or
          // pathlib operations
          apiCall = API::moduleImport("pathlib").getMember("Path").getACall()
        )
      ) and
      // The path argument is typically the first argument
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
