/**
 * @name Insecure HTTP requests or URL handling
 * @description Using urllib or requests without proper validation can lead to SSRF or other attacks
 * @kind path-problem
 * @problem.severity warning
 * @id py/insecure-http
 * @tags security
 *        external/cwe/cwe-918
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module InsecureHttpConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      exists(API::CallNode apiCall |
        apiCall = call.getACall() and
        (
          // urllib.request.urlopen
          apiCall = API::moduleImport("urllib").getMember("request").getMember("urlopen").getACall() or
          // urllib2.urlopen (Python 2 style, but might be imported)
          apiCall = API::moduleImport("urllib2").getMember("urlopen").getACall() or
          // requests.get, requests.post, etc.
          apiCall = API::moduleImport("requests").getMember(["get", "post", "put", "delete", "head", "options"]).getACall() or
          // httpx client
          apiCall = API::moduleImport("httpx").getMember(["get", "post", "put", "delete", "head", "options"]).getACall()
        )
      ) and
      sink = call.getArg(0)  // URL argument
    )
  }
}

module InsecureHttpFlow = TaintTracking::Global<InsecureHttpConfig>;
import InsecureHttpFlow::PathGraph

from InsecureHttpFlow::PathNode source, InsecureHttpFlow::PathNode sink
where InsecureHttpFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Insecure HTTP request with user-controlled URL from $@.", source.getNode(), "user input"
